@verbatim
<template id="finance-workspace-template">
<div class="workspace">
            <a href="#main-content" class="skip-link">Перейти до вмісту</a>
            <div v-if="drawer" class="drawer-scrim" @click="drawer=false"></div>
            <aside ref="drawerEl" :class="['sidebar',{open:drawer}]" id="navigation" aria-label="Головне меню"><a class="brand" :href="url('/')" @click.prevent="navigate('/')"><span class="brand-icon"><icon name="wallet"></icon></span>Finance<span class="brand-dot"></span></a><button class="icon-button close-drawer" aria-label="Закрити меню" @click="drawer=false"><icon name="close"></icon></button><div class="nav-caption">ОСОБИСТИЙ ПРОСТІР</div><nav><a v-for="item in nav" :key="item.name" :href="url(item.path)" :class="['nav-item',{active:activeNav===item.name}]" :aria-current="activeNav===item.name?'page':null" @click.prevent="navigate(item.path)"><icon :name="item.icon"></icon><span>{{item.label}}</span><span v-if="activeNav===item.name" class="nav-dot"></span></a></nav><div class="sidebar-bottom"><div class="sidebar-note"><span class="note-symbol"><icon name="arrow"></icon></span><strong>Маленькі кроки.<br>Великі плани.</strong><p>Кожна запланована витрата наближає до фінансової ясності.</p></div><button class="nav-item logout" :disabled="saving" @click="logout"><icon name="logout"></icon><span>Вийти з кабінету</span></button></div></aside>
            <div class="workspace-body"><header class="topbar"><div class="topbar-left"><button ref="menuEl" class="icon-button mobile-menu" @click="drawer=true" aria-label="Відкрити меню" :aria-expanded="drawer" aria-controls="navigation"><icon name="menu"></icon></button><span class="breadcrumb">Особистий кабінет<span>/</span><strong>{{title}}</strong></span></div><div class="topbar-right"><button class="button tonal topbar-telegram" :disabled="linking" @click="openTelegram()"><icon name="telegram"></icon>{{linking?'Зачекайте…':'Відкрити Telegram-бота'}}</button><span class="today-label"><icon name="calendar"></icon>{{new Intl.DateTimeFormat('uk-UA',{day:'numeric',month:'long'}).format(new Date())}}</span><div class="profile-wrap"><button class="profile" @click="account=!account" :aria-expanded="account" aria-controls="profile-menu"><span class="avatar">{{initial}}</span><span class="profile-copy"><strong>{{user.name||'Користувач'}}</strong><small>Особистий акаунт</small></span></button><button v-if="account" class="profile-scrim" aria-label="Закрити профіль" @click="account=false"></button><div v-if="account" class="profile-menu" id="profile-menu"><strong>{{user.name}}</strong><p>{{user.email}}</p><button class="button text profile-telegram" :disabled="linking" @click="openTelegram()"><icon name="telegram"></icon>Відкрити Telegram-бота</button><button class="button text" :disabled="saving" @click="logout"><icon name="logout"></icon>Вийти</button></div></div></div></header>
            <main id="main-content" :aria-busy="loading"><div v-if="loading" class="loading-line" role="status"><span class="visually-hidden">Завантаження даних</span></div><div v-if="error" class="notice error page-error" role="alert"><span>{{error}}</span><button class="button text" :disabled="loading" @click="load">Спробувати ще</button></div>
            <div class="page-intro"><div><span class="eyebrow">{{view.name==='home'?'ВАША ФІНАНСОВА КАРТИНА':view.name==='tasks'?'ПРОСТІР ДЛЯ ВАЖЛИВОГО':'ВАШІ ФІНАНСИ, ВАШІ ПРАВИЛА'}}</span><h1 id="page-heading" tabindex="-1">{{view.name==='year'?'Бюджет на '+(currentYear?.name||'…')+' рік':view.name==='month'?(currentMonth?.name||'Бюджет місяця')+' '+(currentYear?.name||''):title}}<span v-if="view.name==='home'" class="heading-dot">.</span></h1><p class="muted">{{({home:'Плануйте впевнено. Витрачайте усвідомлено.',year:'Кожен місяць — ще один крок до фінансової ясності.',month:'Керуйте витратами та бюджетами категорій.',transactions:'Усі витрати, деталі та історія в одному місці.',categories:'Зручний порядок у ваших щоденних витратах.',users:'Акаунти кабінету та прив’язка Telegram для статистики й витрат.',tasks:'Звільніть думки для важливого — плани залиште тут.',exchange:'Швидкий перерахунок CNY, USDT та гривні.'})[view.name]}}</p></div><div class="intro-actions"><button v-if="view.name==='home'" class="button primary" :disabled="loading" @click="openDialog('year')"><icon name="plus"></icon>Додати рік</button><button v-if="view.name==='categories'" class="button primary" :disabled="loading" @click="openDialog('category')"><icon name="plus"></icon>Нова категорія</button><button v-if="view.name==='month'" class="button primary" :disabled="loading||!state.budgets.length" @click="openDialog('transaction')"><icon name="plus"></icon>Додати витрату</button><button v-if="view.name==='tasks'" class="button primary" :disabled="loading" @click="openDialog('task')"><icon name="plus"></icon>Нова задача</button><button v-if="view.name==='exchange'" class="button outlined" :disabled="rateBusy" @click="loadRates"><icon name="refresh"></icon>{{rateBusy?'Оновлення…':'Оновити курси'}}</button><a v-if="view.name==='year'" :href="url('/')" class="button outlined" @click.prevent="navigate('/')"><icon name="left"></icon>До огляду</a></div></div>
            <div v-if="loading&&!ready" class="skeleton-layout" aria-label="Завантаження"><div v-for="n in 3" :key="n" class="skeleton"></div><div class="skeleton wide"></div></div>
            <template v-if="ready">
            <overview-page></overview-page>
            <transactions-page></transactions-page>
            <users-page></users-page>
            <categories-page></categories-page>
            <tasks-page></tasks-page>
            <exchange-page></exchange-page>
            </template><footer class="page-footer"><span>Finance<span class="brand-dot"></span></span><span>Більше ясності у ваших фінансах</span></footer></main></div>
            <div v-if="notice" class="toast" role="status"><span><icon name="check"></icon></span>{{notice}}<button class="icon-button" aria-label="Закрити повідомлення" @click="notice=''"><icon name="close"></icon></button></div>
            <app-modal :open="Boolean(dialog)" :title="dialogTitle" :busy="saving" :error="formError" :danger="['deleteTask','deleteTransaction'].includes(dialog)" :confirm-label="['deleteTask','deleteTransaction'].includes(dialog)?'Так, видалити':undefined" @close="closeDialog" @save="save"><template v-if="dialog==='userTelegram'"><p class="dialog-description">{{form.name}}. Вкажіть числовий Telegram ID або очистіть поле, щоб відв’язати Telegram.</p><label class="field">Telegram ID<input v-model="form.telegram_id" type="text" inputmode="numeric" pattern="[1-9][0-9]{0,18}" maxlength="19" placeholder="Наприклад, 123456789"></label><p class="dialog-description">Свій ID можна отримати командою /start у боті. За автоматичним посиланням вводити його не потрібно.</p></template><template v-if="dialog==='year'"><p class="dialog-description">Новий рік — 12 місяців для ваших планів.</p><label class="field">Рік<input v-model="form.year" type="number" min="1900" max="9999" step="1" required></label></template><template v-if="dialog==='category'"><p class="dialog-description">{{form.id?'Оновіть назву — зміни відобразяться в бюджетах і транзакціях.':'Дайте категорії зрозумілу назву.'}}</p><label class="field">Назва категорії<input v-model="form.name" type="text" maxlength="255" placeholder="Наприклад, продукти" required></label></template><template v-if="dialog==='transaction'"><div class="form-grid"><label class="field span-two">Категорія<custom-select v-model="form.category_id" :options="transactionCategories.map(category=>({label:category.name,value:category.id}))" placeholder="Оберіть категорію" aria-label="Категорія" required></custom-select></label><label class="field span-two">Опис витрати<input v-model="form.title" type="text" placeholder="На що витратили?" maxlength="255" required></label><label class="field">Сума, грн<input v-model="form.amount" type="number" min="0" step="0.01" required></label><label class="field">Спосіб оплати<custom-select v-model="form.type" :options="[{label:'Картка',value:'card'},{label:'Готівка',value:'cash'}]" aria-label="Спосіб оплати" required></custom-select></label><label class="field span-two">Дата та час<input v-model="form.created_at" type="datetime-local" required></label></div></template><template v-if="dialog==='budget'"><label class="field">Категорія<custom-select v-model="form.category_id" :options="availableCategories.map(category=>({label:category.name,value:category.id}))" :disabled="Boolean(form.id)" placeholder="Оберіть категорію" aria-label="Категорія бюджету" required></custom-select></label><p v-if="!availableCategories.length" class="dialog-description">Усі категорії вже мають бюджет або ще не створені. Додайте нову в розділі «Категорії».</p><label class="field">Бюджет, грн<input v-model="form.budget" type="number" min="0" step="0.01" required></label><div v-if="form.category_id" class="budget-suggestion"><icon name="arrow"></icon><div><span>Середні місячні витрати за цей рік</span><strong>{{analyticsLoading?'Розраховуємо…':analytics===null?'—':money(analytics)+' грн'}}</strong></div><button v-if="analytics!==null" class="button text" type="button" @click="form.budget=analytics">Використати</button></div></template><template v-if="dialog==='task'"><label class="field">Для кого<custom-select v-model="form.user_id" :options="state.users.map(person=>({label:person.name,value:person.id}))" aria-label="Для кого задача" required></custom-select></label><label class="field">Що потрібно зробити<textarea v-model="form.description" rows="3" maxlength="10000" required placeholder="Додайте свою задачу"></textarea></label><div class="form-grid"><label class="field">Пріоритет<custom-select v-model="form.priority" :options="[{label:'Високий',value:'high'},{label:'Середній',value:'middle'},{label:'Низький',value:'low'}]" aria-label="Пріоритет задачі"></custom-select></label><label class="field">Час<input v-model="form.task_time" type="time"></label><label class="field span-two">Дата<input v-model="form.task_date" type="date" required></label></div></template><template v-if="['deleteTask','deleteTransaction'].includes(dialog)"><p class="dialog-description">Ви впевнені, що хочете видалити {{dialog==='deleteTask'?'цю задачу':'цю транзакцію'}}?</p><div class="delete-summary"><strong>{{dialog==='deleteTask'?form.description:form.title}}</strong><span v-if="dialog==='deleteTransaction'">{{money(form.amount)}} грн</span></div><div class="notice warning">Запис буде видалено. Відновити його через кабінет буде неможливо.</div></template></app-modal>
        </div>
</template>
@endverbatim
